def info(m):
    print(m)


def warn(m):
    print("WARN: " + m, file=sys.stderr)


def die(m, code=1):
    print("ERROR: " + m, file=sys.stderr)
    sys.exit(code)


# ---------------------------------------------------------------------------
# 解码
# ---------------------------------------------------------------------------
def decode_payload():
    raw = "".join(PAYLOAD_B64.split())
    try:
        blob = gzip.decompress(base64.b64decode(raw))
    except Exception as e:
        die("内嵌数据解码失败（脚本可能被截断/破坏）: %s" % e)

    sha = hashlib.sha256(blob).hexdigest()
    if sha != PAYLOAD_SHA256:
        warn("数据校验和不符（期望 %s，实得 %s）——脚本可能被编辑过"
             % (PAYLOAD_SHA256[:16], sha[:16]))

    try:
        rows = json.loads(blob.decode("utf-8"))
    except Exception as e:
        die("内嵌 JSON 解析失败: %s" % e)

    recs = []
    for r in rows:
        if not isinstance(r, list) or len(r) < 4:
            continue
        recs.append({
            "jwt": (r[0] or "").strip(),
            "refresh_token": (r[1] or "").strip(),
            "uid": (r[2] or "").strip(),
            "name": (r[3] or "").strip(),
            "username": (r[4] if len(r) > 4 else "") or "",
            "expires_at": (r[5] if len(r) > 5 else 0) or 0,
            "realm": (r[6] if len(r) > 6 else "cn") or "cn",
        })
    recs = [r for r in recs if r["jwt"]]
    return recs, sha


# ---------------------------------------------------------------------------
# 数据库
# ---------------------------------------------------------------------------
def dsn_parse(dsn, scheme, port):
    from urllib.parse import urlparse, unquote
    if "://" not in dsn:
        dsn = "%s://%s" % (scheme, dsn)
    u = urlparse(dsn)
    return {
        "host": u.hostname or "127.0.0.1",
        "port": u.port or port,
        "user": unquote(u.username) if u.username else None,
        "password": unquote(u.password) if u.password else "",
        "dbname": (u.path or "").lstrip("/") or None,
    }


CANDIDATE_DB_PATHS = (
    "data/gateway.db",
    "./gateway.db",
    "./data/gateway.db",
    "/root/glm/codebuddy2api/data/gateway.db",
    "/opt/codebuddy2api/data/gateway.db",
    os.path.expanduser("~/codebuddy2api/data/gateway.db"),
)


def resolve_sqlite_path(explicit):
    if explicit:
        if not os.path.exists(explicit):
            die("SQLite 文件不存在: %s" % explicit)
        return explicit
    for c in CANDIDATE_DB_PATHS:
        if os.path.exists(c):
            return c
    die("找不到 gateway.db，用 --sqlite-path 指定（候选: %s）"
        % ", ".join(CANDIDATE_DB_PATHS))


def sqlite_connect(path, for_write):
    if for_write:
        bak = "%s.bak.%s" % (path, time.strftime("%Y%m%d-%H%M%S"))
        try:
            shutil.copy2(path, bak)
            info("已备份原库 -> %s" % bak)
        except Exception as e:
            die("备份失败，已中止（避免无备份写库）: %s" % e)
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    return con


def mysql_connect(dsn):
    try:
        import pymysql
    except ImportError:
        die("需要 pymysql：pip install pymysql")
    c = dsn_parse(dsn, "mysql", 3306)
    try:
        return pymysql.connect(host=c["host"], port=c["port"], user=c["user"] or "root",
                               password=c["password"], database=c["dbname"],
                               charset="utf8mb4", connect_timeout=10,
                               cursorclass=pymysql.cursors.DictCursor)
    except Exception as e:
        die("连接 MySQL 失败 (%s:%s/%s): %s" % (c["host"], c["port"], c["dbname"], e))


def pgsql_connect(dsn):
    try:
        import psycopg2
    except ImportError:
        die("需要 psycopg2：pip install psycopg2-binary")
    c = dsn_parse(dsn, "postgresql", 5432)
    try:
        return psycopg2.connect(host=c["host"], port=c["port"], user=c["user"] or "postgres",
                                password=c["password"], dbname=c["dbname"] or "postgres",
                                connect_timeout=10)
    except Exception as e:
        die("连接 PostgreSQL 失败 (%s:%s/%s): %s" % (c["host"], c["port"], c["dbname"], e))


def table_columns(con, db):
    try:
        if db == "sqlite":
            return {r[1] for r in con.execute("PRAGMA table_info(%s)" % TABLE).fetchall()}
        cur = con.cursor()
        if db == "mysql":
            cur.execute("SHOW COLUMNS FROM %s" % TABLE)
            return {r["Field"] for r in cur.fetchall()}
        cur.execute("SELECT column_name FROM information_schema.columns WHERE table_name=%s", (TABLE,))
        return {r[0] for r in cur.fetchall()}
    except Exception as e:
        die("读取表结构失败（表 %s 是否存在？）: %s" % (TABLE, e))


def find_existing(con, db, jwts):
    if not jwts:
        return set()
    exist = set()
    cur = con.cursor()
    for i in range(0, len(jwts), 10):
        chunk = jwts[i:i + 10]
        ph = ",".join(["?" if db == "sqlite" else "%s"] * len(chunk))
        try:
            cur.execute("SELECT jwt FROM %s WHERE jwt IN (%s)" % (TABLE, ph), chunk)
            for r in cur.fetchall():
                v = r[0] if db == "sqlite" else (r["jwt"] if isinstance(r, dict) else r[0])
                if v:
                    exist.add(v)
        except Exception as e:
            die("查询已存在账号失败: %s" % e)
    return exist


def insert_rows(con, db, recs, cols):
    if not recs:
        return 0
    want = ["name", "username", "jwt", "refresh_token", "session_cookie",
            "status", "weight", "user_id", "remark"]
    use = [c for c in want if c in cols]
    if "jwt" not in use:
        die("目标表缺少 jwt 列，表结构不符")

    ph = ",".join(["?" if db == "sqlite" else "%s"] * len(use))
    sql = "INSERT INTO %s (%s) VALUES (%s)" % (TABLE, ",".join(use), ph)

    cur = con.cursor()
    ok = 0
    for r in recs:
        item = {
            "name": r["name"] or r["username"] or "imported",
            "username": r["username"] or "",
            "jwt": r["jwt"],
            "refresh_token": r["refresh_token"] or "",
            "session_cookie": "",
            "status": "enabled",
            "weight": 1,
            "user_id": r["uid"] or "",
            "remark": r["uid"] or "",
        }
        try:
            cur.execute(sql, tuple(item.get(c) for c in use))
            ok += 1
        except Exception as e:
            warn("插入失败: %s" % str(e)[:120])
    con.commit()
    return ok


def update_rows(con, db, recs, cols):
    cur = con.cursor()
    upd = ["refresh_token = %s", "status = 'enabled'"]
    if "user_id" in cols:
        upd.append("user_id = %s")
    sql = "UPDATE %s SET %s WHERE jwt = %s" % (TABLE, ", ".join(upd), "%s")
    if db == "sqlite":
        sql = sql.replace("%s", "?")
    ok = 0
    for r in recs:
        args = [r["refresh_token"] or ""]
        if "user_id" in cols:
            args.append(r["uid"] or "")
        args.append(r["jwt"])
        try:
            cur.execute(sql, args)
            ok += 1
        except Exception as e:
            warn("更新失败: %s" % str(e)[:120])
    con.commit()
    return ok


def verify(con, db):
    cur = con.cursor()
    cur.execute("SELECT COUNT(*) AS n FROM %s" % TABLE)
    r = cur.fetchone()
    total = r[0] if db == "sqlite" else (r["n"] if isinstance(r, dict) else r[0])
    info("库内账号总数: %s" % total)
    if db == "sqlite":
        cur.execute("SELECT name, username, length(jwt) jl, length(refresh_token) rl, status "
                    "FROM %s ORDER BY id DESC LIMIT 5" % TABLE)
        for x in cur.fetchall():
            info("  %-18s %-14s jwt=%s rt=%s %s"
                 % ((x["name"] or "")[:18], (x["username"] or "")[:14],
                    x["jl"], x["rl"], x["status"]))
    return total


# ---------------------------------------------------------------------------
def main():
    ap = argparse.ArgumentParser(
        description="自包含账号导入（274 条数据已内嵌）",
        formatter_class=argparse.RawDescriptionHelpFormatter, epilog=__doc__)
    ap.add_argument("--db", choices=["sqlite", "mysql", "pgsql"], default="sqlite")
    ap.add_argument("--sqlite-path", default="")
    ap.add_argument("--dsn", default="")
    ap.add_argument("--dry-run", action="store_true", help="只解码预览，不写库")
    ap.add_argument("--update", action="store_true", help="已存在账号改为刷新 token")
    ap.add_argument("--verify", action="store_true", help="写完回读校验")
    ap.add_argument("--limit", type=int, default=0, help="只导入前 N 条（调试用）")
    a = ap.parse_args()

    info("== 1. 解码内嵌数据 ==")
    recs, sha = decode_payload()
    if a.limit > 0:
        recs = recs[:a.limit]
    info("解出 %d 条账号（内嵌声明 %d 条）" % (len(recs), PAYLOAD_COUNT))
    info("数据 sha256: %s%s" % (sha, "  ✓ 校验通过" if sha == PAYLOAD_SHA256 else "  ✗ 与声明不符"))

    info("")
    info("%-4s %-10s %-20s %-14s %-6s %s" % ("#", "uid", "昵称", "用户名", "realm", "refresh"))
    info("-" * 74)
    for i, r in enumerate(recs, 1):
        info("%-4d %-10s %-20s %-14s %-6s %s"
             % (i, (r["uid"] or "-")[:10], (r["name"] or "-")[:20],
                (r["username"] or "-")[:14], r["realm"],
                "有" if r["refresh_token"] else "无"))
    n_rt = sum(1 for r in recs if not r["refresh_token"])
    n_uid = sum(1 for r in recs if not r["uid"])
    if n_rt:
        warn("%d 条没有 refresh_token（access 过期后需重新登录）" % n_rt)
    if n_uid:
        warn("%d 条没有 uid" % n_uid)

    if a.dry_run:
        info("")
        info("--dry-run：未写入任何数据。确认无误后去掉 --dry-run 真写库。")
        return

    info("")
    info("== 2. 连接数据库 ==")
    if a.db == "sqlite":
        path = resolve_sqlite_path(a.sqlite_path)
        info("SQLite: %s" % os.path.abspath(path))
        con = sqlite_connect(path, for_write=True)
    elif a.db == "mysql":
        if not a.dsn:
            die("--db mysql 需要 --dsn")
        con = mysql_connect(a.dsn)
    else:
        if not a.dsn:
            die("--db pgsql 需要 --dsn")
        con = pgsql_connect(a.dsn)

    try:
        cols = table_columns(con, a.db)
        info("表 %s 可见列 %d 个%s"
             % (TABLE, len(cols), "" if "user_id" in cols else "（无 user_id 列，将不写该列）"))

        info("")
        info("== 3. 查重 ==")
        exist = find_existing(con, a.db, [r["jwt"] for r in recs])
        new = [r for r in recs if r["jwt"] not in exist]
        old = [r for r in recs if r["jwt"] in exist]
        info("已存在 %d | 全新 %d" % (len(old), len(new)))

        info("")
        info("== 4. 写入 ==")
        ins = insert_rows(con, a.db, new, cols)
        info("插入 %d 行" % ins)
        upd = 0
        if old and a.update:
            upd = update_rows(con, a.db, old, cols)
            info("更新 %d 行" % upd)
        elif old:
            info("跳过 %d 行已存在（要刷新用 --update）" % len(old))

        if a.verify:
            info("")
            info("== 5. 回读校验 ==")
            verify(con, a.db)

        info("")
        info("完成：新增 %d，更新 %d，跳过 %d" % (ins, upd, 0 if a.update else len(old)))
        info("")
        info("导入后：")
        info("  1) 若是 MySQL/PG 库，重启你的 codebuddy2api 服务")
        info("  2) 跑一次额度同步让新号余额入库：")
        info("     curl -H 'Authorization: Bearer <admin-key>' -X POST http://127.0.0.1:8088/admin/sync-credit")
        info("  3) 确认账号列表：curl -H 'Authorization: Bearer <admin-key>' http://127.0.0.1:8088/admin/accounts")
    finally:
        try:
            con.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()
